
.form {
  width: 100%;
  max-width: 560px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.4;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.form-head {
  font-size: 15px;
  font-weight: bold;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 10px;
}

.form-head i {
  margin-right: 8px;
}

.section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 12px;
  color: var(--c-accent);
}

.seg {
  display: flex;
  gap: 8px;
}

.seg-btn {
  flex: 1;
  padding: 8px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-text-muted);
  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
}

.seg-btn.active {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.input {
  width: 100%;
  padding: 8px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-text);
  font-family: inherit;
  font-size: 13px;
}

.input:focus {
  outline: none;
  border-color: var(--c-accent);
}

.check {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.check input {
  accent-color: var(--c-primary);
}

.guardian-row {
  display: flex;
  gap: 6px;
  align-items: center;
}

.guardian-row .input {
  flex: 1;
}

.del {
  padding: 6px 8px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-primary);
  cursor: pointer;
}

.add {
  padding: 6px;
  background: transparent;
  border: 1px dashed var(--c-border);
  border-radius: 6px;
  color: var(--c-text-muted);
  cursor: pointer;
  font-family: inherit;
  font-size: 12px;
}

.submit {
  padding: 12px;
  background: var(--c-primary);
  border: none;
  border-radius: 6px;
  color: #fff;
  font-family: inherit;
  font-size: 14px;
  font-weight: bold;
  cursor: pointer;
}

.submit i {
  margin-right: 6px;
}
